<?php require_once __DIR__.'/auth.php'; $title='Travel Plans'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('plans');if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['id'];$items=array_values(array_filter($items,fn($x)=>(int)$x['id']!==$id));write_data('plans',$items);redirect('plans.php');} ?><div class="row g-3"><?php foreach(array_reverse($items) as $p): ?><div class="col-lg-6"><div class="card shadow-sm p-4"><div class="d-flex justify-content-between"><h5 class="fw-bold"><?=e($p['name'])?></h5><form method="post" onsubmit="return confirm('Delete plan?')"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div><p class="text-muted"><?=e($p['email'])?> · <?=e($p['phone'])?></p><p><strong>Travel:</strong> <?=e($p['arrival_date'])?> → <?=e($p['departure_date'])?><br><strong>Destination:</strong> <?=e($p['destination'])?> · <strong>Budget:</strong> <?=e($p['budget'])?></p><p><strong>Guests:</strong> <?=e($p['adults'])?> adults, <?=e($p['children_6_11'])?> children (6-11), <?=e($p['children_under_5'])?> under 5, <?=e($p['rooms'])?> rooms</p><p><strong>Preferences:</strong> <?=e(implode(', ',$p['preferences']??[]))?><br><strong>Hotel:</strong> <?=e($p['hotel'])?> · <strong>Transport:</strong> <?=e($p['transport'])?></p><div class="bg-light rounded p-3"><?=e($p['requirements'])?></div></div></div><?php endforeach;?><?php if(!$items): ?><div class="col-12 text-center text-muted py-5">No travel plans submitted.</div><?php endif;?></div><?php include 'admin-foot.php'; ?>